import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    a = [list(map(int, data[2 + i * c: 2 + (i + 1) * c])) for i in range(r)]
    NEG = float('-inf')
    # dp[j] = best total for a path ending at (i, j); rows processed from the bottom up
    dp = [NEG] * c
    for i in range(r - 1, -1, -1):
        row = a[i]
        for j in range(c):
            if i == r - 1 and j == 0:
                best = 0
            else:
                best = dp[j]  # arrived from below (dp[j] still holds row i+1)
                if j > 0 and dp[j - 1] > best:
                    best = dp[j - 1]  # arrived from the left (already updated for row i)
            dp[j] = best + row[j]
    print(dp[c - 1])

