import sys

data = sys.stdin.read().split()
r, c = int(data[0]), int(data[1])
a = [list(map(int, data[2 + i * c: 2 + (i + 1) * c])) for i in range(r)]

def best(i, j):
    # best total of a path that starts at (i, j) and ends at (0, c - 1)
    if i == 0 and j == c - 1:
        return a[i][j]
    opts = []
    if i > 0:
        opts.append(best(i - 1, j))
    if j < c - 1:
        opts.append(best(i, j + 1))
    return a[i][j] + max(opts)

print(best(r - 1, 0))

